        if LobbySceneManager and LobbySceneManager.LoadStreamLevel then
            LobbySceneManager.LoadStreamLevel(
                true,
                SOCIAL_HALL_CONFIG.ROOM_SCENE_NAME,
                SOCIAL_HALL_CONFIG.CAMERA_ID,
